def solve(g):
    H=len(g);W=len(g[0])
    out=[row[:] for row in g]
    seen=[[False]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if seen[r][c] or g[r][c]==0: continue
            st=[(r,c)]; seen[r][c]=True; comp=[]
            while st:
                a,b=st.pop(); comp.append((a,b))
                for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                    if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==g[a][b]:
                        seen[x][y]=True; st.append((x,y))
            rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
            rmin,rmax,cmin,cmax=min(rs),max(rs),min(cs),max(cs)
            # layer colors via deduplicated diagonal corner path (skips nested interiors)
            seq=[]; rr,cc=rmin,cmin
            while True:
                seq.append(g[rr][cc]); rr+=1; cc+=1
                if rr>rmax or cc>cmax: break
            uniq=[seq[i] for i in range(len(seq)) if i==0 or seq[i]!=seq[i-1]]
            n=len(uniq)
            for d in range(n):
                col=uniq[n-1-d]
                for a in range(rmin+d,rmax-d+1):
                    for b in range(cmin+d,cmax-d+1):
                        if max(a-rmin,rmax-a,b-cmin,cmax-b)==d: out[a][b]=col
            # core strictly inside innermost band
            for a in range(rmin+n+1,rmax+1):
                for b in range(cmin+n+1,cmax+1):
                    out[a][b]=uniq[-1]
    return out
