                best=c
            if best is None: break
            chain.append(best); used.add(id(best)); cur=best
        chains.append(chain)
    newg=[row[:] for row in g]
    for chain in chains:
        rev=list(reversed([c['cid'] for c in chain]))
        for k,c in enumerate(chain):
            for y in range(c['y0'],c['y1']+1):
                for x in range(c['x0'],c['x1']+1):
